        self,
        func,
        trigger=None,
        args=None,
        kwargs=None,
        id=None,
        name=None,
        misfire_grace_time=undefined,
        coalesce=undefined,
        max_instances=undefined,
        next_run_time=undefined,
        jobstore="default",
        executor="default",
        replace_existing=False,
        **trigger_args,
    ):
        return super().add_job(
            func,
            trigger,
            args,
            kwargs,
            # Override to avoid duplicating the function name everywhere
            id or func.__name__,
            name,
            misfire_grace_time,
            coalesce,
            max_instances,
            next_run_time,
            jobstore,
            executor,
            replace_existing,
            **trigger_args,
        )


class OlAsyncIOScheduler(_NamedJobIdMixin, AsyncIOScheduler):
    def __init__(self):
        super().__init__({'apscheduler.timezone': 'UTC'})
        self.add_listener(
            job_listener, EVENT_JOB_EXECUTED | EVENT_JOB_ERROR | EVENT_JOB_SUBMITTED
        )


class OlBlockingScheduler(_NamedJobIdMixin, BlockingScheduler):
    """Compatibility scheduler for existing synchronous monitoring users."""

    def __init__(self):
        super().__init__({'apscheduler.timezone': 'UTC'})
        self.add_listener(
            job_listener, EVENT_JOB_EXECUTED | EVENT_JOB_ERROR | EVENT_JOB_SUBMITTED
        )


def job_listener(event: JobEvent):
    if event.code == EVENT_JOB_SUBMITTED:
        print(f"Job {event.job_id} has started.", flush=True)
    elif event.code == EVENT_JOB_EXECUTED:
        print(f"Job {event.job_id} completed successfully.", flush=True)
    elif event.code == EVENT_JOB_ERROR:
        print(f"Job {event.job_id} failed.", flush=True)


def bash_run(cmd: str, sources: list[str] | None = None, capture_output=False):
    if not sources:
        sources = []

    source_paths = [
        (
            os.path.join("scripts", "monitoring", source)
            if not os.path.isabs(source)
            else source
        )
        for source in sources
    ]
    bash_command = "\n".join(
        (
            'set -e',
            *(f'source "{path}"' for path in source_paths),
            cmd,
        )
    )

    return subprocess.run(
        [
            "bash",
            "-c",
            bash_command,
        ],
        check=True,
        # Mainly for testing:
        capture_output=capture_output,
        text=capture_output if capture_output else None,
    )


def limit_server(
    allowed_hosts: list[str], scheduler: OlAsyncIOScheduler | OlBlockingScheduler
):
    """
    Remove a decorated job unless this host matches an allowed name or prefix.

    A short name also matches the first label of a fully qualified hostname.
    """

    def decorator(func):
        hostname = os.environ.get("HOSTNAME")
        names = (hostname, hostname.split(".", 1)[0]) if hostname else ()

        def matches(pattern: str) -> bool:
            if pattern.endswith("*"):
                return any(name.startswith(pattern[:-1]) for name in names)
            return pattern in names

        if not any(matches(pattern) for pattern in allowed_hosts):
            # @scheduler.scheduled_job runs first in the stacked decorator form.
            # Find the job by function so explicit job IDs work as well.
            for job in scheduler.get_jobs():
                if job.func is func:
                    scheduler.remove_job(job.id)
        return func

    return decorator


def get_service_ip(image_name: str) -> str:
    """Get a Compose service container's IP address from Docker inspect."""
    container_name = image_name
    if not container_name.startswith("openlibrary-"):
        container_name = f"openlibrary-{container_name}"
    if not container_name.rsplit("-", 1)[-1].isdigit():
        container_name = f"{container_name}-1"

    result = subprocess.run(
        [
            "docker",
            "inspect",
            "--format",
            "{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}",
            container_name,
        ],
        check=True,
        capture_output=True,
        text=True,
    )
    return result.stdout.strip()
